; ============================================================
; Memory (PEEK / POKE / DEEK / DOKE)
; ============================================================

;## kw_lptrtov8
;kw_lptrtov8, <literaladdr>, <destvar>  - PEEK(literal)
kw_lptrtov8:
			pop hl
			ld a, (hl)
			pop hl
			ld (hl), a
			inc hl
			ld (hl), 0
			ret

;## kw_vptrtov8
;kw_vptrtov8, <addrvar>, <destvar>  - PEEK(var)
kw_vptrtov8:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld a, (de)
			pop hl
			ld (hl), a
			inc hl
			ld (hl), 0
			ret

;## kw_ltovptr8
;kw_ltovptr8, <literal>, <addrvar>  - POKE var, literal
kw_ltovptr8:
			pop bc
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			ex de, hl
			ld (hl), c
			ret

;## kw_vtovptr8
;kw_vtovptr8, <sourcevar>, <addrvar>  - POKE var, var
kw_vtovptr8:
			pop hl
			ld c, (hl)
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			ex de, hl
			ld (hl), c
			ret

;## kw_ltolptr8
;kw_ltolptr8, <literal>, <literaladdr>  - POKE literal, literal
kw_ltolptr8:
			pop bc
			pop hl
			ld (hl), c
			ret

;## kw_vtolptr8
;kw_vtolptr8, <sourcevar>, <literaladdr>  - POKE literal, var
kw_vtolptr8:
			pop hl
			ld c, (hl)
			pop hl
			ld (hl), c
			ret

;## kw_vtolptr
;kw_vtolptr, <sourcevar>, <literaladdr>  - DOKE literal, var
kw_vtolptr:
			pop hl
			ld c, (hl)
			inc hl
			ld b, (hl)
			pop hl
			ld (hl), c
			inc hl
			ld (hl), b
			ret

; ============================================================
; Arrays (16 bit elements, no bounds check)
; ============================================================

;## kw_aget
;kw_aget, <arraybase>, <indexvar>, <destvar>
kw_aget:
			pop de
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			add hl, hl
			add hl, de
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_aset
;kw_aset, <arraybase>, <indexvar>, <sourcevar>
kw_aset:
			pop de
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			add hl, hl
			add hl, de
			ex de, hl
			pop hl
			ld c, (hl)
			inc hl
			ld b, (hl)
			ex de, hl
			ld (hl), c
			inc hl
			ld (hl), b
			ret

;## kw_aget8
;kw_aget8, <arraybase>, <indexvar>, <destvar>  - Byte array element (0 .. 255)
kw_aget8:
			pop de
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			add hl, de
			ld a, (hl)
			pop hl
			ld (hl), a
			inc hl
			ld (hl), 0
			ret

;## kw_aset8
;kw_aset8, <arraybase>, <indexvar>, <sourcevar>  - set a Byte array element (low byte)
kw_aset8:
			pop de
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			add hl, de
			ex de, hl
			pop hl
			ld a, (hl)
			ld (de), a
			ret

;## kw_asetl
;kw_asetl, <arraybase>, <indexvar>, <literal>
kw_asetl:
			pop de
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			add hl, hl
			add hl, de
			pop bc
			ld (hl), c
			inc hl
			ld (hl), b
			ret

; ============================================================
; Random (16 bit xorshift 7,9,8 - period 65535)
; ============================================================

;## kw_strcpy
;kw_strcpy, <destaddr>, <srcaddr>  - cut at the destination's capacity byte
kw_strcpy:
			pop de
			pop hl
			dec de
			ld a, (de)
			ld b, a
			inc de
ntc_strcpy_loop:
			ld a, (hl)
			ld (de), a
			or a
			ret z
			inc hl
			inc de
			djnz ntc_strcpy_loop
			xor a
			ld (de), a
			ret

;## kw_strcat
;kw_strcat, <destaddr>, <srcaddr>  - cut at the destination's capacity byte
kw_strcat:
			pop de
			dec de
			ld a, (de)
			ld b, a
			inc de
ntc_strcat_end:
			ld a, (de)
			or a
			jr z, ntc_strcat_copy
			inc de
			djnz ntc_strcat_end
			pop hl
			ret
ntc_strcat_copy:
			pop hl
ntc_strcat_loop:
			ld a, (hl)
			ld (de), a
			or a
			ret z
			inc hl
			inc de
			djnz ntc_strcat_loop
			xor a
			ld (de), a
			ret

;## kw_strlen
;kw_strlen, <straddr>, <destvar>
kw_strlen:
			pop hl
			ld bc, 0
ntc_strlen_loop:
			ld a, (hl)
			or a
			jr z, ntc_strlen_done
			inc hl
			inc c
			jr ntc_strlen_loop
ntc_strlen_done:
			pop hl
			ld (hl), c
			inc hl
			ld (hl), b
			ret

;## kw_strcmpeq
;kw_strcmpeq, <addr1>, <addr2>  - Z if equal
kw_strcmpeq:
			pop de
			pop hl
ntc_streq_loop:
			ld a, (de)
			cp (hl)
			ret nz
			or a
			ret z
			inc hl
			inc de
			jr ntc_streq_loop

;## kw_strcmpne
;kw_strcmpne, <addr1>, <addr2>  - Z if not equal
kw_strcmpne:
			pop de
			pop hl
ntc_strne_loop:
			ld a, (de)
			cp (hl)
			jr nz, ntc_strne_t
			or a
			jr z, ntc_strne_f
			inc hl
			inc de
			jr ntc_strne_loop
ntc_strne_t:
			xor a
			ret
ntc_strne_f:
			inc a
			ret

; ============================================================
; I/O - no firmware, no call, no push. SP stays in the thread.
; Shared routines are entered with jp and the return address in
; IX, and end with jp (ix). Keywords that are done use
; ld ix, ntc_next (a ret) so the routine continues the thread.
; ============================================================

;## ntc_printbuf ntc_data ntc_plat_screen
; print the 0 terminated ASCII text at (ntc_sptr), then ret (thread)
ntc_printbuf:
			ld hl, (ntc_sptr)
			ld a, (hl)
			or a
			ret z
			inc hl
			ld (ntc_sptr), hl
			ld ix, ntc_printbuf
			jp ntc_plat_putc

;## kw_printstrvar ntc_printbuf
;kw_printstrvar, <straddr>
kw_printstrvar:
			pop hl
			ld (ntc_sptr), hl
			jp ntc_printbuf

;## ntc_itoa ntc_data
; HL = signed value, DE = buffer: writes the digits and a 0 (DE ends on
; the 0). jp (ix) back. Uses A, BC, IY.
ntc_itoa:
			bit 7, h
			jr z, ntc_ia_pos
			ld a, '-'
			ld (de), a
			inc de
			xor a
			sub l
			ld l, a
			sbc a, a
			sub h
			ld h, a
ntc_ia_pos:
			xor a
			ld (ntc_lead), a
			ld iy, ntc_pow10
ntc_ia_pow:
			ld c, (iy+0)
			ld b, (iy+1)
			ld a, b
			or c
			jr z, ntc_ia_last
			ld a, '0' - 1
ntc_ia_sub:
			inc a
			and a
			sbc hl, bc
			jr nc, ntc_ia_sub
			add hl, bc
			cp '0'
			jr nz, ntc_ia_out
			ld b, a
			ld a, (ntc_lead)
			or a
			ld a, b
			jr z, ntc_ia_skip
ntc_ia_out:
			ld (de), a
			inc de
			ld a, 1
			ld (ntc_lead), a
ntc_ia_skip:
			inc iy
			inc iy
			jr ntc_ia_pow
ntc_ia_last:
			ld a, l
			add a, '0'
			ld (de), a
			inc de
			xor a
			ld (de), a
			jp (ix)
ntc_pow10:		dw 10000, 1000, 100, 10, 0

;## kw_printint ntc_printbuf ntc_itoa
;kw_printint, <var>  - signed decimal
kw_printint:
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			ld de, ntc_numbuf
			ld ix, ntc_pi_done
			jp ntc_itoa
ntc_pi_done:
			ld hl, ntc_numbuf
			ld (ntc_sptr), hl
			jp ntc_printbuf

;## kw_inp
;kw_inp, <portvar>, <dest>  - Inp(port): in a, (c) with BC = port, 0 .. 255
kw_inp:
			pop hl
			ld c, (hl)
			inc hl
			ld b, (hl)
			in a, (c)
			pop hl
			ld (hl), a
			inc hl
			ld (hl), 0
			ret

;## kw_printnl ntc_data ntc_plat_screen
;kw_printnl
kw_printnl:
			ld ix, ntc_next
			jp ntc_plat_newline

;## ntc_atoi ntc_data
; text to number into the var at (ntc_ivar). ntc_atoi reads ntc_inbuf,
; ntc_atoi_hl reads HL. Spaces first, then - , then digits (or &H hex).
ntc_atoi:
			ld hl, ntc_inbuf
ntc_atoi_hl:
			ld a, (hl)
			cp ' '
			jr nz, ntc_atoi_sign
			inc hl
			jr ntc_atoi_hl
ntc_atoi_sign:
			ld c, 0
			cp '-'
			jr nz, ntc_atoi_amp
			inc c
			inc hl
			ld a, (hl)
ntc_atoi_amp:
			ld de, 0
			cp '&'
			jr nz, ntc_atoi_loop
			inc hl
			ld a, (hl)
			or #20
			cp 'h'
			jr nz, ntc_atoi_done
			inc hl
ntc_atoi_hex:
			ld a, (hl)
			sub '0'
			jr c, ntc_atoi_done
			cp 10
			jr c, ntc_atoi_hd
			or #20
			sub 'a' - '0'
			jr c, ntc_atoi_done
			cp 6
			jr nc, ntc_atoi_done
			add a, 10
ntc_atoi_hd:
			ex de, hl
			add hl, hl
			add hl, hl
			add hl, hl
			add hl, hl
			or l
			ld l, a
			ex de, hl
			inc hl
			jr ntc_atoi_hex
ntc_atoi_loop:
			ld a, (hl)
			sub '0'
			jr c, ntc_atoi_done
			cp 10
			jr nc, ntc_atoi_done
			ld (ntc_aptr), hl
			ex de, hl
			ld d, h
			ld e, l
			add hl, hl
			add hl, hl
			add hl, de
			add hl, hl
			ld e, a
			ld d, 0
			add hl, de
			ex de, hl
			ld hl, (ntc_aptr)
			inc hl
			jr ntc_atoi_loop
ntc_atoi_done:
			ld a, c
			or a
			jr z, ntc_atoi_store
			xor a
			sub e
			ld e, a
			sbc a, a
			sub d
			ld d, a
ntc_atoi_store:
			ld hl, (ntc_ivar)
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_inkey ntc_data ntc_plat_key
;kw_inkey, <destvar>  - new key press or 0, no wait
kw_inkey:
			pop hl
			ld (ntc_ivar), hl
			ld ix, ntc_inkey_got
			jp ntc_plat_scankey
ntc_inkey_got:
			ld hl, (ntc_ivar)
			ld (hl), a
			inc hl
			ld (hl), 0
			ret

;## kw_locatell ntc_data ntc_plat_screen
;kw_locatell, <x>, <y>  - 1 based
kw_locatell:
			pop bc
			pop de
			ld h, c
			ld l, e
			ld ix, ntc_next
			jp ntc_plat_locate

;## ntc_getn ntc_data
; BC = address of a word: A = its value limited to 0..255
; (below 0 = 0, above 255 = 255). jp (ix) back. Keeps DE, HL.
ntc_getn:
			ld a, (bc)
			ld (ntc_gnlo), a
			inc bc
			ld a, (bc)
			or a
			jp m, ntc_gn_zero
			jr nz, ntc_gn_max
			ld a, (ntc_gnlo)
			jp (ix)
ntc_gn_zero:
			xor a
			jp (ix)
ntc_gn_max:
			ld a, 255
			jp (ix)

;## kw_strleft ntc_getn
;kw_strleft, <dest>, <src>, <nvar>  - Left$(src, n)
kw_strleft:
			pop de
			pop hl
			pop bc
			ld ix, ntc_sl_n
			jp ntc_getn
ntc_sl_n:
			ld b, a
; copy up to B chars from HL to DE, then the 0
ntc_strncpy:
			inc b
ntc_sn_loop:
			dec b
			jr z, ntc_sn_end
			ld a, (hl)
			or a
			jr z, ntc_sn_end
			ld (de), a
			inc hl
			inc de
			jr ntc_sn_loop
ntc_sn_end:
			xor a
			ld (de), a
			ret

;## kw_strright ntc_getn kw_strleft
;kw_strright, <dest>, <src>, <nvar>  - Right$(src, n)
kw_strright:
			pop de
			pop hl
			pop bc
			ld ix, ntc_sr_n
			jp ntc_getn
ntc_sr_n:
			ld c, a
			ld (ntc_sptr), hl
			ld b, 0
ntc_sr_len:
			ld a, (hl)
			or a
			jr z, ntc_sr_got
			inc hl
			inc b
			jr ntc_sr_len
ntc_sr_got:
			ld a, b
			sub c
			jr nc, ntc_sr_skip
			xor a
ntc_sr_skip:
			ld hl, (ntc_sptr)
			ld c, a
			ld b, 0
			add hl, bc
			ld b, 255
			jp ntc_strncpy

;## kw_strmid ntc_getn kw_strleft
;kw_strmid, <dest>, <src>, <startvar>, <lenvar>  - Mid$(src, start, len)
kw_strmid:
			pop de
			pop hl
			pop bc
			ld ix, ntc_sm_s
			jp ntc_getn
ntc_sm_s:
			or a
			jr z, ntc_sm_s1
			dec a
ntc_sm_s1:
			ld b, a
			inc b
ntc_sm_skip:
			dec b
			jr z, ntc_sm_len
			ld a, (hl)
			or a
			jr z, ntc_sm_len
			inc hl
			jr ntc_sm_skip
ntc_sm_len:
			pop bc
			ld ix, ntc_sm_n
			jp ntc_getn
ntc_sm_n:
			ld b, a
			jp ntc_strncpy

;## kw_strchr
;kw_strchr, <dest>, <nvar>  - Chr$(n)
kw_strchr:
			pop de
			pop hl
			ld a, (hl)
			ld (de), a
			inc de
			xor a
			ld (de), a
			ret

;## kw_strstr ntc_itoa
;kw_strstr, <dest>, <nvar>  - Str$(n): a space before 0 and positives
kw_strstr:
			pop de
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			bit 7, h
			jr nz, ntc_st_go
			ld a, ' '
			ld (de), a
			inc de
ntc_st_go:
			ld ix, ntc_next
			jp ntc_itoa

;## kw_strhex
;kw_strhex, <dest>, <nvar>  - Hex$(n), no leading zeros
kw_strhex:
			pop de
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			ld b, 4
			ld c, 0
ntc_hx_loop:
			xor a
			add hl, hl
			rla
			add hl, hl
			rla
			add hl, hl
			rla
			add hl, hl
			rla
			bit 0, c
			jr nz, ntc_hx_out
			or a
			jr nz, ntc_hx_first
			ld a, b
			dec a
			jr nz, ntc_hx_next
			xor a
ntc_hx_first:
			set 0, c
ntc_hx_out:
			add a, '0'
			cp '9' + 1
			jr c, ntc_hx_put
			add a, 7
ntc_hx_put:
			ld (de), a
			inc de
ntc_hx_next:
			djnz ntc_hx_loop
			xor a
			ld (de), a
			ret

;## kw_strspace ntc_getn
;kw_strspace, <dest>, <nvar>  - Space$(n)
kw_strspace:
			pop de
			pop bc
			ld ix, ntc_sp_n
			jp ntc_getn
ntc_sp_n:
			ld c, ' '
; A = count (NTC_STRMAX at most), C = char, DE = dest
ntc_strfill:
	IF NTC_STRMAX < 255
			cp NTC_STRMAX + 1
			jr c, ntc_sf_ok
			ld a, NTC_STRMAX
ntc_sf_ok:
	ENDIF
			ld b, a
			inc b
ntc_sf_loop:
			dec b
			jr z, ntc_sf_end
			ld a, c
			ld (de), a
			inc de
			jr ntc_sf_loop
ntc_sf_end:
			xor a
			ld (de), a
			ret

;## kw_strucase
;kw_strucase, <dest>, <src>  - UCase$
kw_strucase:
			pop de
			pop hl
ntc_uc_loop:
			ld a, (hl)
			cp 'a'
			jr c, ntc_uc_put
			cp 'z' + 1
			jr nc, ntc_uc_put
			sub 32
ntc_uc_put:
			ld (de), a
			or a
			ret z
			inc hl
			inc de
			jr ntc_uc_loop

;## kw_strrtrim ntc_data
;kw_strrtrim, <dest>, <src>  - RTrim$
kw_strrtrim:
			pop de
			pop hl
			ld (ntc_sptr), de
ntc_rt_copy:
			ld a, (hl)
			ld (de), a
			or a
			jr z, ntc_rt_back
			inc hl
			inc de
			jr ntc_rt_copy
ntc_rt_back:
			ld hl, (ntc_sptr)
			ex de, hl
ntc_rt_loop:
			or a
			sbc hl, de
			add hl, de
			ret z
			dec hl
			ld a, (hl)
			cp ' '
			ret nz
			ld (hl), 0
			jr ntc_rt_loop

;## kw_strtrim kw_strrtrim
;kw_strtrim, <dest>, <src>  - Trim$
kw_strtrim:
			pop de
			pop hl
ntc_tr_skip:
			ld a, (hl)
			cp ' '
			jr nz, ntc_tr_go
			inc hl
			jr ntc_tr_skip
ntc_tr_go:
			ld (ntc_sptr), de
			jp ntc_rt_copy

;## kw_strasc
;kw_strasc, <src>, <destvar>  - Asc(src), 0 if empty
kw_strasc:
			pop hl
			ld a, (hl)
			pop hl
			ld (hl), a
			inc hl
			ld (hl), 0
			ret

;## kw_strval ntc_atoi
;kw_strval, <src>, <destvar>  - Val(src): decimal or &H hex
kw_strval:
			pop hl
			pop de
			ld (ntc_ivar), de
			jp ntc_atoi_hl

;## kw_strinstr ntc_getn ntc_data
;kw_strinstr, <startvar>, <s1>, <s2>, <destvar>  - InStr(start, s1, s2)
kw_strinstr:
			pop bc
			ld ix, ntc_in_s
			jp ntc_getn
ntc_in_s:
			or a
			jr nz, ntc_in_s1
			inc a
ntc_in_s1:
			ld c, a
			pop hl
			ld b, a
ntc_in_adv:
			dec b
			jr z, ntc_in_try0
			ld a, (hl)
			or a
			jr z, ntc_in_nfpop
			inc hl
			jr ntc_in_adv
ntc_in_try0:
			pop de
			ld (ntc_sptr), de
ntc_in_try:
			ld (ntc_iptr), hl
			ld de, (ntc_sptr)
ntc_in_cmp:
			ld a, (de)
			or a
			jr z, ntc_in_found
			cp (hl)
			jr nz, ntc_in_next
			inc hl
			inc de
			jr ntc_in_cmp
ntc_in_next:
			ld hl, (ntc_iptr)
			ld a, (hl)
			or a
			jr z, ntc_in_nf
			inc hl
			inc c
			jr ntc_in_try
ntc_in_nfpop:
			pop de
ntc_in_nf:
			ld c, 0
ntc_in_found:
			pop hl
			ld (hl), c
			inc hl
			ld (hl), 0
			ret

;## ntc_saddr ntc_data
; DE = base, HL = index var address, (ntc_sasz) = element size:
; HL = base + index * size. jp (ix)
ntc_saddr:
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			ld a, (ntc_sasz + 1)		; element size 256 (String Max 255): index * 256
			or a
			jr z, ntc_sa_mul
			ld h, l
			ld l, 0
			add hl, de
			jp (ix)
ntc_sa_mul:
			ld b, h
			ld c, l
			ld hl, 0
			ld a, (ntc_sasz)
ntc_sa_bit:
			srl a
			jr nc, ntc_sa_no
			add hl, bc
ntc_sa_no:
			sla c
			rl b
			or a
			jr nz, ntc_sa_bit
			add hl, de
			jp (ix)
ntc_sasz:		dw 0

;## kw_sget ntc_saddr
;kw_sget, <arraybase>, <indexvar>, <dest>, <element size>  - dest = array(index)
kw_sget:
			pop de
			pop hl
			pop bc
			ld (ntc_sgd), bc
			pop bc
			ld (ntc_sasz), bc
			ld ix, ntc_sg_a
			jp ntc_saddr
ntc_sg_a:
			ld de, (ntc_sgd)
			ld bc, (ntc_sasz)
			ldir
			ret
ntc_sgd:		dw 0

;## kw_sset ntc_saddr kw_strcpy
;kw_sset, <arraybase>, <indexvar>, <src>, <element size>  - array(index) = src, cut at the element
kw_sset:
			pop de
			pop hl
			pop bc
			ld (ntc_sgs), bc
			pop bc
			ld (ntc_sasz), bc
			ld ix, ntc_ssa
			jp ntc_saddr
ntc_ssa:
			ex de, hl
			ld hl, (ntc_sgs)
			ld a, (ntc_sasz)
			dec a
			ld b, a
			jp ntc_strcpy_loop
ntc_sgs:		dw 0

; ============================================================
; Array parameters and dynamic arrays. A procedure gets the address of a
; 12 byte descriptor: dw base, lower bound 1, lower bound 2, count 1,
; count 2, element size. The call stub copies it into the parameter's own
; descriptor; ReDim fills a dynamic array's descriptor.
; ============================================================

;## ntc_ldata
ntc_la:			ds 4
ntc_lb:			ds 4
ntc_lr:			ds 4
ntc_lt:			ds 4
ntc_lsgn:		db 0
ntc_lcnt:		db 0
ntc_ldst:		dw 0
ntc_lix:		dw 0

;## kw_l_mov
;kw_l_mov, <src>, <dest>  - dest = src (4 bytes)
kw_l_mov:
			pop hl
			pop de
			ldi
			ldi
			ldi
			ldi
			ret

;## kw_l_itol
;kw_l_itol, <intvar>, <dest>  - Integer to Long (sign extended)
kw_l_itol:
			pop hl
			pop de
			ld a, (hl)
			ld (de), a
			inc hl
			inc de
			ld a, (hl)
			ld (de), a
			inc de
			rla
			sbc a, a
			ld (de), a
			inc de
			ld (de), a
			ret

;## kw_l_add
;kw_l_add, <a>, <b>, <dest>  - a + b
kw_l_add:
			pop hl
			pop de
			pop ix
			ld a, (de)
			add a, (hl)
			ld (ix+0), a
			inc hl
			inc de
			ld a, (de)
			adc a, (hl)
			ld (ix+1), a
			inc hl
			inc de
			ld a, (de)
			adc a, (hl)
			ld (ix+2), a
			inc hl
			inc de
			ld a, (de)
			adc a, (hl)
			ld (ix+3), a
			ret

;## kw_l_sub
;kw_l_sub, <a>, <b>, <dest>  - a - b
kw_l_sub:
			pop de
			pop hl
			pop ix
			ld a, (de)
			sub (hl)
			ld (ix+0), a
			inc hl
			inc de
			ld a, (de)
			sbc a, (hl)
			ld (ix+1), a
			inc hl
			inc de
			ld a, (de)
			sbc a, (hl)
			ld (ix+2), a
			inc hl
			inc de
			ld a, (de)
			sbc a, (hl)
			ld (ix+3), a
			ret

;## kw_l_and
;kw_l_and, <a>, <b>, <dest>
kw_l_and:
			pop hl
			pop de
			pop ix
			ld a, (de)
			and (hl)
			ld (ix+0), a
			inc hl
			inc de
			ld a, (de)
			and (hl)
			ld (ix+1), a
			inc hl
			inc de
			ld a, (de)
			and (hl)
			ld (ix+2), a
			inc hl
			inc de
			ld a, (de)
			and (hl)
			ld (ix+3), a
			ret

;## ntc_lcmp ntc_ldata
; DE = a, HL = b: work out a - b. ntc_lsgn = #80 if a < b (signed),
; ntc_lcnt = 0 if a = b. jp (ix) back.
ntc_lcmp:
			ld a, (de)
			sub (hl)
			ld (ntc_lr), a
			inc hl
			inc de
			ld a, (de)
			sbc a, (hl)
			ld (ntc_lr+1), a
			inc hl
			inc de
			ld a, (de)
			sbc a, (hl)
			ld (ntc_lr+2), a
			inc hl
			inc de
			ld a, (de)
			sbc a, (hl)
			ld (ntc_lr+3), a
			ld b, 0
			jp po, ntc_lcm_nov
			ld b, #80
ntc_lcm_nov:
			xor b
			and #80
			ld (ntc_lsgn), a
			ld hl, ntc_lr
			ld a, (hl)
			inc hl
			or (hl)
			inc hl
			or (hl)
			inc hl
			or (hl)
			ld (ntc_lcnt), a
			jp (ix)

;## kw_l_cpge ntc_lcmp
;kw_l_cpge, <a>, <b>  - Z if a >= b
kw_l_cpge:
			pop de
			pop hl
			ld ix, ntc_lcge
			jp ntc_lcmp
ntc_lcge:
			ld a, (ntc_lsgn)
			or a
			ret

;## ntc_lmul ntc_ldata
; ntc_la * ntc_lb -> ntc_lr (low 32 bits, same signed / unsigned). jp (ix)
ntc_lmul:
			ld hl, 0
			ld (ntc_lr), hl
			ld (ntc_lr+2), hl
			ld b, 32
ntc_lm_loop:
			ld hl, ntc_lb+3
			srl (hl)
			dec hl
			rr (hl)
			dec hl
			rr (hl)
			dec hl
			rr (hl)
			jr nc, ntc_lm_skip
			ld de, ntc_la
			ld hl, ntc_lr
			ld a, (de)
			add a, (hl)
			ld (hl), a
			inc de
			inc hl
			ld a, (de)
			adc a, (hl)
			ld (hl), a
			inc de
			inc hl
			ld a, (de)
			adc a, (hl)
			ld (hl), a
			inc de
			inc hl
			ld a, (de)
			adc a, (hl)
			ld (hl), a
ntc_lm_skip:
			ld hl, ntc_la
			sla (hl)
			inc hl
			rl (hl)
			inc hl
			rl (hl)
			inc hl
			rl (hl)
			djnz ntc_lm_loop
			jp (ix)

;## kw_l_mul ntc_lmul ntc_ldata
;kw_l_mul, <a>, <b>, <dest>  - a * b
kw_l_mul:
			pop hl
			ld de, ntc_la
			ldi
			ldi
			ldi
			ldi
			pop hl
			ld de, ntc_lb
			ldi
			ldi
			ldi
			ldi
			pop hl
			ld (ntc_ldst), hl
			ld ix, ntc_lmu_back
			jp ntc_lmul
ntc_lmu_back:
			ld hl, ntc_lr
; copy the 4 bytes at HL to (ntc_ldst), then next keyword
ntc_lstore:
			ld de, (ntc_ldst)
			ldi
			ldi
			ldi
			ldi
			ret

;## ntc_ltoa ntc_ldata ntc_data
; Long at (HL) to text at DE, 0 at the end. jp (ix) back. Uses IY.
ntc_ltoa:
			ld (ntc_ldst), de
			ld de, ntc_la
			ldi
			ldi
			ldi
			ldi
			ld de, (ntc_ldst)
			ld a, (ntc_la+3)
			or a
			jp p, ntc_lta_pos
			ld a, '-'
			ld (de), a
			inc de
			ld hl, ntc_la
			xor a
			sub (hl)
			ld (hl), a
			inc hl
			ld a, 0
			sbc a, (hl)
			ld (hl), a
			inc hl
			ld a, 0
			sbc a, (hl)
			ld (hl), a
			inc hl
			ld a, 0
			sbc a, (hl)
			ld (hl), a
ntc_lta_pos:
			xor a
			ld (ntc_lead), a
			ld iy, ntc_lpow10
ntc_lta_pow:
			ld a, (iy+0)
			or (iy+1)
			or (iy+2)
			or (iy+3)
			jr z, ntc_lta_last
			ld c, '0'
ntc_lta_sub:
			ld hl, ntc_la
			ld a, (hl)
			sub (iy+0)
			ld (ntc_lt), a
			inc hl
			ld a, (hl)
			sbc a, (iy+1)
			ld (ntc_lt+1), a
			inc hl
			ld a, (hl)
			sbc a, (iy+2)
			ld (ntc_lt+2), a
			inc hl
			ld a, (hl)
			sbc a, (iy+3)
			ld (ntc_lt+3), a
			jr c, ntc_lta_dig
			ld hl, (ntc_lt)
			ld (ntc_la), hl
			ld hl, (ntc_lt+2)
			ld (ntc_la+2), hl
			inc c
			jr ntc_lta_sub
ntc_lta_dig:
			ld a, c
			cp '0'
			jr nz, ntc_lta_out
			ld a, (ntc_lead)
			or a
			jr z, ntc_lta_skip
			ld a, c
ntc_lta_out:
			ld (de), a
			inc de
			ld a, 1
			ld (ntc_lead), a
ntc_lta_skip:
			ld bc, 4
			add iy, bc
			jr ntc_lta_pow
ntc_lta_last:
			ld a, (ntc_la)
			add a, '0'
			ld (de), a
			inc de
			xor a
			ld (de), a
			jp (ix)
ntc_lpow10:		dd 1000000000, 100000000, 10000000, 1000000, 100000, 10000, 1000, 100, 10, 0

;## kw_l_str ntc_ltoa
;kw_l_str, <dest>, <long>  - Str$(Long): a space before 0 and positives
kw_l_str:
			pop de
			pop hl
			inc hl
			inc hl
			inc hl
			bit 7, (hl)
			dec hl
			dec hl
			dec hl
			jr nz, ntc_lst_go
			ld a, ' '
			ld (de), a
			inc de
ntc_lst_go:
			ld ix, ntc_next
			jp ntc_ltoa

;## kw_bssinit ntc_data ntc_plat_memtop ntc_plat_screen kw_stop @shared
;kw_bssinit, <start>, <size>  - the start of the main thread: the program's arrays live after
;  it (from ntc_end, not in its file). Check they fit under the platform's top (and 256 bytes
;  under the real stack when that is above them), then clear them. Too big: a message, the
;  program stops.
kw_bssinit:
			pop hl
			ld (ntc_bsa), hl
			pop bc
			ld (ntc_bsz), bc
			ld (ntc_bsp), sp
			ld sp, (ntc_csp)
			add hl, bc				; HL = their end
			ex de, hl
			call ntc_plat_memtop	; HL = the platform's top
			or a
			sbc hl, de
			jr c, ntc_bs_big
			ld hl, (ntc_csp)		; the real stack, when above them
			ld bc, (ntc_bsa)
			or a
			sbc hl, bc
			jr c, ntc_bs_ok
			ld hl, (ntc_csp)
			ld bc, -256
			add hl, bc
			or a
			sbc hl, de
			jr c, ntc_bs_big
ntc_bs_ok:
			ld bc, (ntc_bsz)
			ld a, b
			or c
			jr z, ntc_bs_done
			ld hl, (ntc_bsa)
			ld (hl), 0
			dec bc
			ld a, b
			or c
			jr z, ntc_bs_done
			ld d, h
			ld e, l
			inc de
			ldir
ntc_bs_done:
			ld sp, (ntc_bsp)
			ret
ntc_bs_big:
			ld hl, ntc_bstxt
ntc_bs_pl:
			ld a, (hl)
			or a
			jr z, ntc_bs_stop
			inc hl
			ld (ntc_bsa), hl
			ld ix, ntc_bs_pn
			jp ntc_plat_putc
ntc_bs_pn:
			ld hl, (ntc_bsa)
			jr ntc_bs_pl
ntc_bs_stop:
			ld ix, kw_stop
			jp ntc_plat_newline
ntc_bsa:		dw 0
ntc_bsz:		dw 0
ntc_bsp:		dw 0
ntc_bstxt:		db "GURU 001", 0

;## ntc_plat_data
ntc_curx:		db 0			; column (0 based) - counted for Tab
ntc_cury:		db 0			; not used (a stream has no rows)
ntc_scols:		db 80			; columns
ntc_bdosa:		db 0			; ntc_bdos: A on return
ntc_smode:		db 2			; screen mode (Graphics on an Amstrad CPC: CP/M's console is mode 2)
ntc_cpmtop:		dw #FFFF		; the heap's top if lower than the BDOS (Graphics on CP/M Plus: GFH_AT)
				ds 256			; the program's real stack
ntc_cpmstack:

;## ntc_plat_bdos ntc_plat_data ntc_data @shared
; ------------------------------------------------------------
; ntc_bdos - C = BDOS function, DE = argument. A (also in ntc_bdosa)
; and HL come back. IX is kept. Interrupts are on during the call.
; ------------------------------------------------------------
ntc_bdos:
			ld (ntc_hostix), ix
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ei
			call 5
			di
			ld sp, (ntc_ip)
			ld (ntc_bdosa), a
			ld ix, (ntc_hostix)
			jp (ix)

;## ntc_plat_screen ntc_plat_bdos ntc_plat_data ntc_data
; ntc_plat_putc - A = character: BDOS 6, count the column
ntc_plat_putc:
			ld e, a
			ld c, 6
			ld (ntc_pclink), ix
			ld ix, ntc_pc_back
			jp ntc_bdos
ntc_pc_back:
			ld ix, (ntc_pclink)
			ld a, (ntc_scols)
			ld b, a
			ld a, (ntc_curx)
			inc a
			cp b
			jr c, ntc_pc_col
			xor a					; the terminal wrapped
ntc_pc_col:
			ld (ntc_curx), a
			jp (ix)

; ntc_plat_newline - CR LF
ntc_plat_newline:
			ld (ntc_pclink), ix
			ld e, 13
			ld c, 6
			ld ix, ntc_nl_lf
			jp ntc_bdos
ntc_nl_lf:
			ld e, 10
			ld c, 6
			ld ix, ntc_nl_done
			jp ntc_bdos
ntc_nl_done:
			xor a
			ld (ntc_curx), a
			ld ix, (ntc_pclink)
			jp (ix)

ntc_pclink:		dw 0

;## ntc_plat_cls @unit ntc_plat_screen ntc_plat_bdos ntc_plat_data ntc_data
	IF NTC_TERM = 0
; ntc_plat_cls - a stream can't be cleared: a new line (unless at the start)
ntc_plat_cls:
			ld a, (ntc_curx)
			or a
			jp nz, ntc_plat_newline
			jp (ix)

; ntc_plat_locate - nothing on a stream
ntc_plat_locate:
			jp (ix)
	ELSE
; ntc_plat_cls - clear and home with the terminal's codes
ntc_plat_cls:
			xor a
			ld (ntc_curx), a
			ld hl, ntc_term_cls
			jp ntc_cpm_puts

; ntc_plat_locate - H = column, L = row, 1 based (kept on an 80 x 24 screen)
ntc_plat_locate:
			ld a, h
			or a
			jr nz, ntc_lc_x
			inc a
ntc_lc_x:
			cp 81
			jr c, ntc_lc_xok
			ld a, 80
ntc_lc_xok:
			ld h, a
			dec a
			ld (ntc_curx), a
			ld a, l
			or a
			jr nz, ntc_lc_y
			inc a
ntc_lc_y:
			cp 25
			jr c, ntc_lc_yok
			ld a, 24
ntc_lc_yok:
			ld l, a
			ld de, ntc_term_buf
		IF NTC_TERM = 1
			; VT52: ESC Y row+31 column+31
			ld a, 27
			ld (de), a
			inc de
			ld a, 'Y'
			ld (de), a
			inc de
			ld a, l
			add a, 31
			ld (de), a
			inc de
			ld a, h
			add a, 31
			ld (de), a
			inc de
		ELSE
			; ANSI: ESC [ row ; column H
			ld a, 27
			ld (de), a
			inc de
			ld a, '['
			ld (de), a
			inc de
			ld a, l
			ld b, '0' - 1
ntc_lc_r10:
			inc b
			sub 10
			jr nc, ntc_lc_r10
			add a, 10 + '0'
			ld c, a
			ld a, b
			cp '0'
			jr z, ntc_lc_r1
			ld (de), a
			inc de
ntc_lc_r1:
			ld a, c
			ld (de), a
			inc de
			ld a, ';'
			ld (de), a
			inc de
			ld a, h
			ld b, '0' - 1
ntc_lc_c10:
			inc b
			sub 10
			jr nc, ntc_lc_c10
			add a, 10 + '0'
			ld c, a
			ld a, b
			cp '0'
			jr z, ntc_lc_c1
			ld (de), a
			inc de
ntc_lc_c1:
			ld a, c
			ld (de), a
			inc de
			ld a, 'H'
			ld (de), a
			inc de
		ENDIF
			xor a
			ld (de), a
			ld hl, ntc_term_buf
			jp ntc_cpm_puts

; ntc_cpm_puts - HL = 0 terminated codes, each through BDOS 6
ntc_cpm_puts:
			ld (ntc_cplink), ix
ntc_cps_loop:
			ld a, (hl)
			or a
			jr z, ntc_cps_done
			inc hl
			ld (ntc_cpsp), hl
			ld e, a
			ld c, 6
			ld ix, ntc_cps_next
			jp ntc_bdos
ntc_cps_next:
			ld hl, (ntc_cpsp)
			jr ntc_cps_loop
ntc_cps_done:
			ld ix, (ntc_cplink)
			jp (ix)
ntc_cplink:		dw 0
ntc_cpsp:		dw 0
ntc_term_buf:	ds 10
		IF NTC_TERM = 1
ntc_term_cls:	db 27, "E", 27, "H", 0		; VT52: clear, home
		ELSE
ntc_term_cls:	db 27, "[2J", 27, "[H", 0	; ANSI: clear, home
		ENDIF
	ENDIF

;## ntc_plat_key ntc_plat_bdos ntc_data
; ntc_plat_scankey - A = key or 0 (BDOS 6, E = #FF)
ntc_plat_scankey:
			ld e, #FF
			ld c, 6
			jp ntc_bdos

; ntc_plat_getkey - wait for a key (BDOS 6 until there is one)
ntc_plat_getkey:
			ld (ntc_gklink), ix
ntc_gk_poll:
			ld e, #FF
			ld c, 6
			ld ix, ntc_gk_back
			jp ntc_bdos
ntc_gk_back:
			or a
			jr z, ntc_gk_poll
			ld ix, (ntc_gklink)
			jp (ix)
ntc_gklink:		dw 0

;## ntc_plat_exit ntc_plat_data
; ntc_plat_exit - warm boot back to CP/M
ntc_plat_exit:
			jp 0

; ============================================================
; File system (FileSystem class) - BDOS files, FCBs, 128 byte records
; ============================================================
; The class's methods are keywords: they take their arguments
; into fs_a1 .. fs_a3, the result's address into fs_res, and
; jump to fs_go with HL = the routine. fs_go runs the routine on
; the real stack (call / push are fine there, as for BDOS), with
; interrupts on, and stores its HL result at fs_res (fs_go4: a
; Long, high word in fs_hi; fs_go0: no store - the routine writes
; the result itself). A routine that fails jumps to fs_err with
; HL = the status (negative); fs_err unwinds to fs_go.
;
; Slots: 0 is for Load / Save / Delete / Exists / Rename / Size,
; 1 and 2 are the handles Open gives. A slot is FS_SLOT bytes:
;   +0  FCB (36)    +36 mode (0 free, 1 read, 2 write, 3 update)
;   +37 position in the buffer (0-128)
;   +38 buffer state (0 not loaded, 1 loaded, 2 changed)
;   +39 record number in the buffer (2)   +42 buffer (128)
; Every record goes through random read / write (BDOS 33 / 34),
; so reading, writing and Seek all work the same way.

FS_SLOT		equ 170
FS_MODE		equ 36
FS_BPOS		equ 37
FS_BST		equ 38
FS_RECL		equ 39
FS_RECH		equ 40
FS_BUF		equ 42
FS_MAXH		equ 2

FS_NOTFOUND	equ -2
FS_FULL		equ -3
FS_BADNAME	equ -4
FS_NOHANDLE	equ -5
FS_BADHANDLE	equ -6
FS_EOF		equ -7
FS_TOOBIG	equ -8
FS_FAILED	equ -9
FS_EXISTS	equ -10
FS_BADMODE	equ -11

;## ntc_plat_cmdline ntc_data
; the command line (System.CommandLine): the start code copies CP/M's command
; tail (#80: its length, then the text - CP/M has made it capitals) here first,
; before a disc call or Input can overwrite it
ntc_cmdbuf:		ds 128
; ntc_cmdsave - (call, the start code) #80 into ntc_cmdbuf, 0 ended, without the
; spaces in front
ntc_cmdsave:
			ld hl, #80
			ld b, (hl)
			inc hl
			ld de, ntc_cmdbuf
			ld a, b
			or a
			jr z, ntc_cs_end
ntc_cs_sp:
			ld a, (hl)
			cp ' '
			jr nz, ntc_cs_cp
			inc hl
			djnz ntc_cs_sp
			jr ntc_cs_end
ntc_cs_cp:
			ld a, (hl)
			ld (de), a
			inc hl
			inc de
			djnz ntc_cs_cp
ntc_cs_end:
			xor a
			ld (de), a
			ret
; ntc_cmdget - (on the thread) HL = the result String: the command line, cut at
; its capacity
ntc_cmdget:
			dec hl
			ld c, (hl)
			inc hl
			ex de, hl
			ld hl, ntc_cmdbuf
ntc_cg_lp:
			ld a, (hl)
			or a
			jr z, ntc_cg_end
			inc c
			dec c
			jr z, ntc_cg_end
			ld (de), a
			inc hl
			inc de
			dec c
			jr ntc_cg_lp
ntc_cg_end:
			xor a
			ld (de), a
			ret

;## ntc_plat_memtop ntc_plat_data
; ntc_plat_memtop - HL = the first byte the Memory class's Small heap must not
; use: the BDOS (its address is at 6; the CCP below it is free, the program
; ends with a warm boot), or ntc_cpmtop when lower (Graphics on CP/M Plus sets
; it to its copy at GFH_AT). Called on the real stack (call / ret), only by the
; Memory class.
ntc_plat_memtop:
			push de
			ld hl, (ntc_cpmtop)
			ld de, (6)
			or a
			sbc hl, de
			add hl, de
			jr c, ntc_mt1			; ntc_cpmtop lower
			ex de, hl
ntc_mt1:
			pop de
			ret


ntc_end:				; the end of the program (and of its file)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bssfrom	equ ntc_end
ntc_bss		equ ntc_bssfrom
arr_ty		equ ntc_bss + 0		; 128 bytes
arr_pw		equ ntc_bss + 128		; 128 bytes
arr_ox		equ ntc_bss + 256		; 128 bytes
arr_oy		equ ntc_bss + 384		; 128 bytes
arr_ow		equ ntc_bss + 512		; 128 bytes
arr_oh		equ ntc_bss + 640		; 128 bytes
arr_va		equ ntc_bss + 768		; 128 bytes
arr_cg		equ ntc_bss + 896		; 128 bytes
arr_own		equ ntc_bss + 1024		; 128 bytes
arr_tx		equ ntc_bss + 1152		; 2624 bytes
arr_ex		equ ntc_bss + 3776		; 128 bytes
arr_hb		equ ntc_bss + 3904		; 1024 bytes
arr_zo		equ ntc_bss + 4928		; 32 bytes
arr_http_b		equ ntc_bss + 4960		; 16 bytes
arr_http_e		equ ntc_bss + 4976		; 16 bytes
arr_http_ip		equ ntc_bss + 4992		; 4 bytes
arr_http_cip		equ ntc_bss + 4996		; 4 bytes
arr_cybsys_b		equ ntc_bss + 5000		; 64 bytes
arr_cybsys_pm		equ ntc_bss + 5064		; 128 bytes
arr_toback_t		equ ntc_bss + 5192		; 32 bytes
ntc_bss_size	equ 5224
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
ntc_memtab	equ ntc_free		; the Memory class's tables
			ASSERT ntc_free <= #EF00, "the program and its arrays must end below #EF00 (CyborgOS: the slot's stub is #EF00-#FFFF)"
			SAVEAMSDOS "GUI.CYB", ntc_start, ntc_end - ntc_start, ntc_start
